actual_old_state_decode:
`timescale 1ns/1ps
module actual_state_decode(input wire [3:0] state_i, output wire quiesce_o,resume_o);
    wire w4;
    wire w5;
    assign w4 = (16'hBCFF >> {state_i[0], state_i[2], state_i[1], state_i[3]}) & 1'b1; // u_managed/runtime/clocks/transaction/rate_quiesce_s
    assign w5 = (16'h0130 >> {state_i[1], state_i[0], state_i[2], state_i[3]}) & 1'b1; // u_managed/runtime/n669_s1
    assign quiesce_o=w4;
    assign resume_o=w5;
endmodule

